def part(k, pin):
    grp, text, url = S[k]
    s = text + (', ' + pin if pin else '') + ('' if (not pin and text.endswith('.')) else '.')
    if url:
        s += ' URL: ' + url
    return s


def footnote(parts):
    out = []
    for k, pin in parts:
        out.append(pin if k == '#' else part(k, pin))
    return ' '.join(x if x.endswith(':') else x for x in out).replace('. См.:', '. См.:')
